"use strict";
import { supabase } from "./supabase.js";
const $=id=>document.getElementById(id), esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
const E={};document.querySelectorAll("[id]").forEach(x=>E[x.id]=x);
const S={ctx:null,escopo:"ATIVAS",itens:[],pagina:1,tamanho:20,total:0,atual:null,detalhe:null,historico:[],ultimoFoco:null,confirmar:null,cpfVisivel:false,cpfCompleto:null,cpfCarregando:false,csvExportando:false,dilacaoRevisao:false,dilacoes:[],dilacaoPendente:null,csvColunas:[]};
const errors={VERSAO_DESATUALIZADA:"O indício foi atualizado. Recarregue e tente novamente.",CICLO_NAO_PERMITE_MOVIMENTACAO:"Este Ciclo de Tratamento Interno não permite movimentação.",PROCESSO_SEI_JA_VINCULADO_AO_CICLO:"Este processo já está vinculado.",NUMERO_PROCESSO_SEI_INVALIDO:"Número de processo inválido.",USUARIO_SEM_PARTICIPACAO_ATIVA:"Você não possui participação ativa neste ciclo.",JUSTIFICATIVA_SOLICITACAO_MUITO_CURTA:"A justificativa da solicitação deve ter pelo menos 10 caracteres.",PRAZO_SOLICITADO_DEVE_SER_POSTERIOR_AO_ATUAL:"A nova data deve ser posterior ao prazo vigente.",SOLICITACAO_DILACAO_PENDENTE_JA_EXISTE:"Já existe uma solicitação de dilação aguardando análise para este ciclo.",VERSAO_DESATUALIZADA:"O ciclo foi atualizado. Recarregue os dados e tente novamente.",DILACAO_AINDA_NAO_DISPONIVEL:"A solicitação ficará disponível quando faltarem até 7 dias corridos para o vencimento.",TRATAMENTO_AINDA_NAO_INICIADO:"Inicie o tratamento antes de solicitar a dilação.",CICLO_SEM_PRAZO_DEFINIDO:"O Ciclo de Tratamento Interno não possui prazo definido.",CPF_NAO_DISPONIVEL:"O CPF completo não está disponível para este indício.",OPERADOR_SEM_ACESSO_AO_INDICIO:"Você não possui autorização para consultar os dados deste indício.",SOLICITACAO_DILACAO_NAO_PODE_SER_CANCELADA:"A solicitação não está mais disponível para cancelamento.",JUSTIFICATIVA_CANCELAMENTO_MUITO_CURTA:"Informe uma justificativa de cancelamento com pelo menos 10 caracteres."};
const fmtDate=v=>v?new Date(v).toLocaleDateString("pt-BR"):"Não informado",fmtDT=v=>v?new Date(v).toLocaleString("pt-BR"):"Não informado",todayId=()=>Number(new Date().toISOString().slice(0,10).replaceAll("-",""));
const msg=(el,text,type="")=>{el.hidden=!text;el.className=`status-banner ${type}`;el.textContent=text||""}, friendly=e=>errors[e?.message]||e?.message||"Não foi possível concluir a operação.";
const statusClass=c=>({DISPONIVEL_PARA_ATRIBUICAO:"status-available",PENDENTE:"status-pending",PENDENTE_DE_TRATAMENTO:"status-pending",EM_TRATAMENTO:"status-progress",AGUARDANDO_VALIDACAO_TCU:"status-external",ENCERRADO_INTERNAMENTE:"status-closed",VALIDADO_TCU:"status-validated",CANCELADO:"status-cancelled",ESTADO_MISTO_REQUER_ANALISE:"status-analysis"}[c]||"status-neutral");
const badge=statusClass;
const priorityClass=c=>/URGENTE|CRITICA/.test(String(c||""))?"priority-urgent":/ALTA/.test(String(c||""))?"priority-high":/BAIXA/.test(String(c||""))?"priority-low":/NORMAL|MEDIA/.test(String(c||""))?"priority-normal":"priority-undefined";
const deadlineClass=c=>({PRAZO_VENCIDO:"PRAZO_VENCIDO",ATRASADA:"PRAZO_VENCIDO",VENCE_HOJE:"VENCE_HOJE",VENCE_EM_ATE_3_DIAS:"VENCE_EM_ATE_3_DIAS",ATE_3_DIAS:"VENCE_EM_ATE_3_DIAS",VENCE_EM_ATE_7_DIAS:"VENCE_EM_ATE_7_DIAS",ATE_7_DIAS:"VENCE_EM_ATE_7_DIAS",DENTRO_DO_PRAZO:"DENTRO_DO_PRAZO",NO_PRAZO:"DENTRO_DO_PRAZO",ACIMA_7_DIAS:"DENTRO_DO_PRAZO",SEM_PRAZO:"SEM_PRAZO"}[c]||"NAO_APLICAVEL");
const LABELS={
 prazo:{ATRASADA:"Prazo vencido",VENCE_HOJE:"Vence hoje",ATE_3_DIAS:"Vence em até 3 dias",ATE_7_DIAS:"Vence em até 7 dias",NO_PRAZO:"Prazo confortável",SEM_PRAZO:"Sem prazo definido",ACIMA_7_DIAS:"Vence após 7 dias",ATRASADAS:"Prazo vencido",VENCEM_HOJE:"Vence hoje"},
 status:{PENDENTE:"Aguardando início",PENDENTE_DE_TRATAMENTO:"Aguardando início",EM_TRATAMENTO:"Em tratamento",ENCERRADO_INTERNAMENTE:"Tratamento encerrado",AGUARDANDO_VALIDACAO_TCU:"Aguardando validação do TCU",VALIDADO_TCU:"Validado pelo TCU"},
 atividade:{INICIO_TRATAMENTO:"Tratamentos iniciados",OBSERVACAO:"Observações registradas",PROVIDENCIA:"Providências adotadas",VINCULO_PROCESSO_SEI:"Processos SEI vinculados",INATIVACAO_PROCESSO_SEI:"Processos SEI inativados",ALTERACAO_PROCESSO_SEI_PRINCIPAL:"Alterações do processo principal",ENCERRAMENTO_INTERNO:"Tratamentos encerrados"}
};
const labelPrazo=v=>LABELS.prazo[v]||String(v||"").replaceAll("_"," ").toLowerCase().replace(/(^|\s)\S/g,m=>m.toUpperCase());
const labelStatus=(codigo,nome)=>LABELS.status[codigo]||nome||"Situação não informada";
const draftKey=t=>`operador:rascunho:${S.atual?.id_ciclo_tratamento}:${t}`;
async function rpc(name,args={}){const{data,error}=await supabase.rpc(name,args);if(error)throw error;return data}
async function context(){const{data:{session}}=await supabase.auth.getSession();if(!session){location.replace("../index.html");throw Error("SESSAO_AUSENTE")};const{data,error}=await supabase.schema("api").from("v_meu_contexto").select("*").limit(1).maybeSingle();if(error||!data)throw error||Error("CONTEXTO_AUSENTE");if(!["OPERADOR_SEGEP_CE","GESTOR_DADOS_SISTEMA"].includes(data.codigo_perfil)){location.replace("./inicio.html");throw Error("PERFIL_NAO_AUTORIZADO")};S.ctx=data;E.usuarioNome.textContent=data.nome_exibicao;E.usuarioPerfil.textContent=data.nome_perfil;E.voltarGestaoBtn.hidden=data.codigo_perfil!=="GESTOR_DADOS_SISTEMA"}
function params(){return{p_escopo:S.escopo,p_busca:E.busca.value||null,p_situacao:E.status.value||null,p_codigo_prioridade:E.prioridade.value||null,p_codigo_papel:E.papel.value||null,p_situacao_prazo:E.prazo.value||null,p_situacao_processo_sei:E.processo.value||null,p_ordenacao:E.ordem.value,p_pagina:S.pagina,p_tamanho_pagina:S.tamanho}}
async function loadList(){E.estadoTabela.hidden=false;E.estadoTabela.innerHTML="<strong>Carregando indícios...</strong>";try{const d=await rpc("listar_minhas_demandas",params());S.itens=d.itens||[];S.total=d.paginacao?.total_registros||0;renderTable(d.paginacao);fillFilters();msg(E.mensagem,"")}catch(e){msg(E.mensagem,friendly(e),"error")}}
function fillFilters(){const current=E.prioridade.value,values=[...new Map(S.itens.filter(x=>x.codigo_prioridade).map(x=>[x.codigo_prioridade,x.nome_prioridade])).entries()];E.prioridade.innerHTML='<option value="">Todas</option>'+values.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join("");E.prioridade.value=current}
function plural(n,one,many){return `${n} ${Number(n)===1?one:many}`}
function closedAt(x={}){return x.encerrado_em||x.data_encerramento||x.encerramento_em||x.concluido_em||null}
function renderTable(pg={}){
 const concluded=S.escopo==="CONCLUIDAS";
 if(E.colunaDataTitulo)E.colunaDataTitulo.textContent=concluded?"Data do encerramento":"Prazo";
 E.total.textContent=S.total;
 E.pendentes.textContent=S.itens.filter(x=>["PENDENTE","PENDENTE_DE_TRATAMENTO"].includes(x.codigo_status_ciclo)).length;
 E.tratando.textContent=S.itens.filter(x=>x.codigo_status_ciclo==="EM_TRATAMENTO").length;
 E.atrasadas.textContent=S.itens.filter(x=>["ATRASADA","PRAZO_VENCIDO"].includes(x.situacao_prazo)).length;
 E.resumoTabela.textContent=plural(S.total,"indício encontrado","indícios encontrados");
 E.paginaInfo.textContent=`Página ${pg.pagina||1} de ${Math.max(pg.total_paginas||1,1)}`;
 E.anterior.disabled=(pg.pagina||1)<=1;E.proxima.disabled=(pg.pagina||1)>=Math.max(pg.total_paginas||1,1);
 E.estadoTabela.hidden=S.itens.length>0;if(!S.itens.length)E.estadoTabela.innerHTML="<strong>Nenhum indício encontrado.</strong><span>Revise os filtros aplicados.</span>";
 E.tbody.innerHTML=S.itens.map(x=>`<tr><td class="indicio-cell"><strong>${esc(x.identificador_do_indicio)}</strong><small>${esc(x.base_de_dados||"")}</small></td><td class="person-cell"><strong>${esc(x.nome_atual||"Nome não disponível")}</strong><span>${esc(maskCpf(x.cpf_mascarado))}</span></td><td><div class="clip2" title="${esc(x.tipo_indicio||"")}">${esc(x.tipo_indicio||"")}</div></td><td><div class="clip2" title="${esc(x.situacoes_funcionais_resumo||"Não informado")}">${esc(x.situacoes_funcionais_resumo||"Não informado")}</div></td><td class="process-cell">${x.processo_sei_principal?`<span class="process-number">${esc(x.processo_sei_principal)}</span><small>${Number(x.quantidade_processos_sei_ativos)>1?`+${Number(x.quantidade_processos_sei_ativos)-1} ${Number(x.quantidade_processos_sei_ativos)-1===1?"adicional":"adicionais"}`:""}</small>`:"Nenhum processo"}</td><td><span class="badge ${statusClass(x.codigo_status_ciclo)}">${esc(labelStatus(x.codigo_status_ciclo,x.nome_status_ciclo))}</span></td><td><span class="priority-badge ${priorityClass(x.codigo_prioridade)}">${esc(x.nome_prioridade||"Não definida")}</span></td>${concluded?`<td class="closing-date"><strong>${fmtDT(closedAt(x))}</strong><small>Encerramento do ciclo</small></td>`:`<td><span class="deadline-label ${deadlineClass(x.situacao_prazo)}"><strong>${fmtDate(x.prazo_em)}</strong><span>${esc(labelPrazo(x.situacao_prazo))}</span></span></td>`}<td>${esc(x.nome_papel||"")}</td><td><button class="btn btn-secondary" data-view="${x.id_ciclo_tratamento}" type="button"><span class="details-icon" aria-hidden="true"></span><span>Detalhes</span></button></td></tr>`).join("");
}
async function loadPanel(){try{const d=await rpc("resumo_painel_operador",{p_data_inicial:E.painelInicio.value,p_data_final:E.painelFim.value,p_codigo_papel:null,p_id_tipo_indicio:null,p_codigo_prioridade:null});const c=d.cards||{};E.metricasPainel.innerHTML=[["Aguardando início",c.pendentes,"var(--warning)"],["Em análise",c.em_tratamento,"var(--success)"],["Prazo próximo",c.proximas_prazo,"var(--primary)"],["Prazo vencido",c.atrasadas,"var(--danger)"],["Concluídas no período",c.concluidas_periodo,"#7c3aed"],["Tempo médio de tratamento",c.tempo_medio_tratamento_dias==null?"-":`${c.tempo_medio_tratamento_dias} d`,"#475467"]].map(([l,v,color])=>`<article class="metric" style="--accent:${color};--soft:var(--surface-2)"><span>${l}</span><strong>${v??0}</strong><small>Período selecionado</small></article>`).join("");bars(E.graficoStatus,(d.por_status||[]).map(x=>({...x,rotulo:labelStatus(x.codigo_status,x.nome_status)})),"rotulo","status");bars(E.graficoPrazos,(d.por_prazo||[]).map(x=>({...x,rotulo:labelPrazo(x.faixa)})),"rotulo","prazo");bars(E.graficoTipos,d.por_tipo_indicio,"tipo_indicio","tipo");bars(E.graficoAtividades,(d.atividades_por_tipo||[]).map(x=>({...x,rotulo:LABELS.atividade[x.codigo_movimentacao]||x.nome_movimentacao})),"rotulo","atividade");columns(E.graficoConclusoes,d.concluidas_por_dia)}catch(e){msg(E.mensagem,friendly(e),"error")}}
function bars(el,data,label,tone="default"){if(!data?.length){el.innerHTML='<div class="empty-chart">Sem dados no período.</div>';return}const max=Math.max(...data.map(x=>+x.quantidade),1),palettes={status:["#f59e0b","#10b981","#3b82f6","#8b5cf6","#ef4444"],prazo:["#ef4444","#f97316","#f59e0b","#eab308","#3b82f6","#64748b"],tipo:["#7c3aed","#2563eb","#0891b2","#059669","#d97706"],atividade:["#8b5cf6","#10b981","#2563eb","#f97316","#06b6d4","#ef4444"]},palette=palettes[tone]||palettes.status,unit=tone==="atividade"?"registro":"demanda";el.innerHTML=`<div class="bar-chart chart-tone-${tone}" role="img" aria-label="Gráfico de barras">`+data.map((x,i)=>{const q=+x.quantidade,color=palette[i%palette.length];return`<div class="bar-row" style="--bar-color:${color}"><span class="bar-label" title="${esc(x[label])}">${esc(x[label]||"Não informado")}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.max((q/max)*100,q?4:0)}%"></span></span><span class="bar-value" title="${q} ${unit}${q===1?'':'s'}">${q}</span></div>`}).join("")+`<p class="chart-note">As barras mostram a distribuição proporcional de ${unit}s no período selecionado.</p></div>`}
function columns(el,data){if(!data?.length){el.innerHTML='<div class="empty-chart">Sem dados.</div>';return}const max=Math.max(...data.map(x=>+x.quantidade),1),step=Math.max(1,Math.ceil(data.length/7));el.innerHTML='<div class="daily-chart" role="img" aria-label="Indícios concluídos por dia"><div class="line-chart">'+data.map((x,i)=>`<div class="daily-column-wrap"><div class="line-column" title="${fmtDate(x.data)}: ${x.quantidade}" style="height:${Math.max((+x.quantidade/max)*100,2)}%"><span>${x.quantidade||""}</span></div>${i%step===0||i===data.length-1?`<time>${new Date(x.data+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}</time>`:'<time aria-hidden="true"></time>'}</div>`).join("")+'</div></div>'}
function section(title,html){return`<h3 class="section-title">${esc(title)}</h3><div class="detail-grid-v3">${html}</div>`}function card(l,v,c=""){return`<div class="detail-card ${c}"><span>${esc(l)}</span><strong>${esc(v??"Não informado")}</strong></div>`}

function formatCpf(v){const n=String(v||"").replace(/\D/g,"");return n.length===11?n.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,"$1.$2.$3-$4"):null}
function maskCpf(v){const s=String(v||"").trim();if(/^\*{3}\.\d{3}\.\d{3}-\*{2}$/.test(s))return s;const n=s.replace(/\D/g,"");return n.length===11?`***.${n.slice(3,6)}.${n.slice(6,9)}-**`:"CPF protegido"}
function cpfMask(){return maskCpf(S.detalhe?.cpf_mascarado||S.atual?.cpf_mascarado)}
function canRevealCpf(){const p=S.detalhe?.permissoes||{};const permitido=[p.pode_revelar_cpf,p.pode_visualizar_cpf,S.detalhe?.pode_revelar_cpf,S.detalhe?.pode_visualizar_cpf].some(Boolean);return permitido||Boolean(S.atual?.id_indicio&&cpfMask()!=="CPF protegido")}
function updateCpfControl(){if(!E.alternarCpfModalBtn)return;const completo=formatCpf(S.cpfCompleto);E.mCpf.textContent=S.cpfVisivel&&completo?completo:cpfMask();E.alternarCpfModalBtn.hidden=!canRevealCpf();E.alternarCpfModalBtn.disabled=S.cpfCarregando;E.alternarCpfModalBtn.textContent=S.cpfCarregando?"Consultando...":S.cpfVisivel?"Ocultar CPF":"Mostrar CPF";E.alternarCpfModalBtn.setAttribute("aria-pressed",String(S.cpfVisivel))}
async function toggleCpf(){if(S.cpfCarregando||!canRevealCpf())return;if(S.cpfVisivel){S.cpfVisivel=false;updateCpfControl();return}if(S.cpfCompleto){S.cpfVisivel=true;updateCpfControl();return}try{S.cpfCarregando=true;updateCpfControl();let data;try{data=await rpc("revelar_cpf_demanda_operador",{p_id_indicio:Number(S.atual.id_indicio)})}catch(e){if(!/function|rpc|404|not found|PGRST202/i.test(String(e?.message||"")))throw e;data=await rpc("revelar_cpf_indicio_operador",{p_id_indicio:Number(S.atual.id_indicio)})}const completo=formatCpf(data?.cpf);if(!completo)throw Error("CPF_NAO_DISPONIVEL");S.cpfCompleto=completo;S.cpfVisivel=true;msg(E.modalMensagem,"")}catch(e){S.cpfCompleto=null;S.cpfVisivel=false;msg(E.modalMensagem,e.message==="CPF_NAO_DISPONIVEL"?"O CPF completo não está disponível para este indício.":friendly(e),"error")}finally{S.cpfCarregando=false;updateCpfControl()}}

async function carregarDilacoesDoCiclo(idCiclo){try{const data=await rpc("listar_minhas_solicitacoes_dilacao",{p_id_ciclo_tratamento:Number(idCiclo),p_codigo_status:null,p_pagina:1,p_tamanho_pagina:20});S.dilacoes=data?.itens||[];S.dilacaoPendente=S.dilacoes.find(x=>x.codigo_status_solicitacao==="PENDENTE")||null}catch(e){S.dilacoes=[];S.dilacaoPendente=null;console.warn("Não foi possível carregar as solicitações de dilação.",e)}}
async function openModal(id){const item=S.itens.find(x=>String(x.id_ciclo_tratamento)===String(id));if(!item)return;S.ultimoFoco=document.activeElement;S.atual=item;S.cpfVisivel=false;S.cpfCompleto=null;S.cpfCarregando=false;S.detalhe=await rpc("obter_detalhes_demanda_operador",{p_id_indicio:item.id_indicio,p_id_ciclo_tratamento:item.id_ciclo_tratamento});await carregarDilacoesDoCiclo(item.id_ciclo_tratamento);E.modalOverlay.hidden=false;document.body.style.overflow="hidden";E.modalOverlay.querySelector(".operator-modal").focus();E.mNumero.textContent=item.identificador_do_indicio;E.mNome.textContent=item.nome_atual;E.mCpf.textContent=maskCpf(item.cpf_mascarado);E.mTipo.textContent=item.tipo_indicio;E.mStatus.textContent=labelStatus(item.codigo_status_ciclo,item.nome_status_ciclo);E.mStatus.className=`badge ${badge(item.codigo_status_ciclo)}`;E.mPrioridade.textContent=item.nome_prioridade||"Não definida";E.mPrioridade.className=`priority-context ${priorityClass(item.codigo_prioridade)}`;E.mPrazo.textContent=closedAt(item)?fmtDT(closedAt(item)):fmtDate(item.prazo_em);E.mPrazo.className=closedAt(item)?"closing-context":`deadline-context ${deadlineClass(item.situacao_prazo)}`;E.mPapel.textContent=item.nome_papel;E.mProcessos.textContent=(S.detalhe.processos_sei||[]).filter(x=>x.processo_ativo).length;updateCpfControl();renderDetails();renderTreatment();renderProcesses();await loadHistory();switchTab("detalhes")}
function renderDetails(){const d=S.detalhe,c=d.ciclo_selecionado||{};E.painelDetalhes.innerHTML=section("Identificação",card("Número do indício",d.identificador_do_indicio)+card("Base de dados",d.base_de_dados)+card("Tipo",d.tipo_indicio,"wide")+card("Descrição",d.descricao_indicio,"full"))+section("Pessoa",card("Nome",d.nome_atual,"wide")+card("CPF",cpfMask())+card("Situação funcional",d.situacoes_funcionais_resumo||d.situacao_funcional,"full"))+section("Ciclo",card("Número do ciclo",c.numero_ciclo)+card("Situação",c.nome_status_ciclo)+card("Retorno",c.indicador_retorno?"Sim":"Não")+card("Resultado",c.resultado_encerramento,"full"))}
function restoreDraft(id,type){const el=$(id),v=localStorage.getItem(draftKey(type));if(el&&v){el.value=v;el.insertAdjacentHTML("afterend",'<div class="draft-notice">Rascunho recuperado.</div>')}if(el)el.addEventListener("input",()=>localStorage.setItem(draftKey(type),el.value))}
function dataInputMin(){return new Intl.DateTimeFormat("en-CA",{timeZone:"America/Fortaleza",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}
function diasAtePrazo(v){if(!v)return null;const hoje=new Date(dataInputMin()+"T12:00:00"),prazo=new Date(String(v).slice(0,10)+"T12:00:00");return Math.ceil((prazo-hoje)/86400000)}
function tratamentoIniciado(c={}){return Boolean(c.iniciado_em||S.atual?.iniciado_em||S.atual?.codigo_status_ciclo==="EM_TRATAMENTO")}
function dilacaoDisponivel(p,c){const prazo=c.prazo_em||S.atual?.prazo_em,dias=diasAtePrazo(prazo);return !p.somente_leitura&&tratamentoIniciado(c)&&prazo&&dias!==null&&dias<=7}
function rotuloStatusDilacao(s){return({PENDENTE:"Aguardando análise",APROVADA:"Dilação aprovada",APROVADA_COM_AJUSTE:"Aprovada com ajuste",REJEITADA:"Solicitação rejeitada",CANCELADA:"Solicitação cancelada",PERDEU_OBJETO:"Solicitação sem efeito"})[s]||s||"Não informada"}
function dilacaoPendenteCard(x){return `<article class="deadline-request-card request-status"><header><div><span class="card-kicker">Solicitação de dilação</span><h3>${esc(rotuloStatusDilacao(x.codigo_status_solicitacao))}</h3></div><span class="badge status-pending">Em análise</span></header><div class="dilation-compare"><div><span>Prazo no envio</span><strong>${fmtDate(x.prazo_vigente_em)}</strong></div><div><span>Prazo solicitado</span><strong>${fmtDate(x.prazo_solicitado_em)}</strong></div><div><span>Enviada em</span><strong>${fmtDT(x.criado_em||x.solicitado_em)}</strong></div></div><div class="review-reason"><span>Justificativa</span><p>${esc(x.justificativa_solicitante||x.justificativa||"Não informada")}</p></div><p>O prazo vigente permanece inalterado enquanto a solicitação aguarda a análise do Gestor.</p><div class="dilation-actions"><button class="btn btn-danger" id="dilacaoCancelar" type="button">Cancelar solicitação</button></div></article>`}
function dilacaoCard(p,c){const prazo=c.prazo_em||S.atual?.prazo_em,dias=diasAtePrazo(prazo);if(S.dilacaoPendente)return dilacaoPendenteCard(S.dilacaoPendente);if(p.somente_leitura)return `<article class="deadline-request-card disabled"><header><div><span class="card-kicker">Prazo do ciclo</span><h3>Solicitação de dilação</h3></div><span class="badge badge-neutral">Indisponível</span></header><p>Ciclos encerrados ou anteriores não permitem solicitação de dilação.</p></article>`;if(!tratamentoIniciado(c))return `<article class="deadline-request-card disabled"><header><div><span class="card-kicker">Prazo do ciclo</span><h3>Solicitação de dilação</h3></div><span class="badge badge-neutral">Após o início</span></header><p>A solicitação ficará disponível depois que o tratamento for iniciado.</p></article>`;if(!prazo)return `<article class="deadline-request-card disabled"><header><div><span class="card-kicker">Prazo do ciclo</span><h3>Solicitação de dilação</h3></div><span class="badge badge-neutral">Sem prazo</span></header><p>O ciclo não possui prazo vigente para solicitar dilação.</p></article>`;if(dias>7)return `<article class="deadline-request-card disabled"><header><div><span class="card-kicker">Prazo do Ciclo de Tratamento Interno</span><h3>Dilação ainda não disponível</h3></div><span class="deadline-label ${deadlineClass(S.atual?.situacao_prazo)}"><strong>${fmtDate(prazo)}</strong><span>${dias} dias restantes</span></span></header><p>A solicitação ficará disponível quando faltarem até 7 dias corridos para o vencimento.</p></article>`;return `<article class="deadline-request-card"><header><div><span class="card-kicker">Prazo do Ciclo de Tratamento Interno</span><h3>Solicitar dilação de prazo</h3></div><span class="deadline-label ${deadlineClass(S.atual?.situacao_prazo)}"><strong>${fmtDate(prazo)}</strong><span>${dias<0?"Prazo vencido":dias===0?"Vence hoje":`${dias} dias restantes`}</span></span></header><p>Informe a nova data pretendida e justifique a necessidade. O prazo vigente só será alterado após a aprovação do Gestor.</p><div class="dilation-form" id="dilacaoForm"><label class="field"><span>Nova data pretendida</span><input class="control" id="dilacaoData" type="date" min="${dataInputMin()}"></label><label class="field full"><span>Justificativa <small id="dilacaoContador">0/1.500</small></span><textarea class="control textarea" id="dilacaoJustificativa" maxlength="1500" placeholder="Descreva o motivo da solicitação, as providências já adotadas e o período adicional necessário."></textarea></label><div class="dilation-actions full"><button class="btn btn-primary" id="dilacaoRevisar" type="button">Revisar solicitação</button></div></div><div class="dilation-review" id="dilacaoRevisao" hidden></div></article>`}
async function enviarDilacao(data,text){const c=S.detalhe.ciclo_selecionado||{};try{msg(E.modalMensagem,"Enviando solicitação...");await rpc("solicitar_dilacao_prazo_operador",{p_id_ciclo_tratamento:Number(c.id_ciclo_tratamento||S.atual.id_ciclo_tratamento),p_versao_esperada:Number(c.versao_ciclo||c.versao||S.atual.versao_ciclo),p_prazo_solicitado_em:`${data}T23:59:59-03:00`,p_justificativa:text});await carregarDilacoesDoCiclo(c.id_ciclo_tratamento||S.atual.id_ciclo_tratamento);await loadHistory();renderTreatment();msg(E.modalMensagem,"Solicitação enviada ao Gestor. O prazo atual foi preservado.","success")}catch(e){msg(E.modalMensagem,friendly(e),"error")}}
async function cancelarDilacao(){const x=S.dilacaoPendente;if(!x)return;const ok=await confirm("Cancelar solicitação de dilação",`<p>A solicitação será cancelada e não poderá mais ser analisada.</p><label class="field"><span>Justificativa</span><textarea class="control textarea" id="cancelDilacaoMotivo" maxlength="1000"></textarea></label>`,"Cancelar solicitação");if(!ok)return;const motivo=$("cancelDilacaoMotivo")?.value.trim();if(!motivo||motivo.length<10)return msg(E.modalMensagem,"Informe uma justificativa com pelo menos 10 caracteres.","warning");try{await rpc("cancelar_solicitacao_dilacao_operador",{p_id_solicitacao_dilacao:Number(x.id_solicitacao_dilacao),p_justificativa:motivo});await carregarDilacoesDoCiclo(S.atual.id_ciclo_tratamento);await loadHistory();renderTreatment();msg(E.modalMensagem,"Solicitação cancelada.","success")}catch(e){msg(E.modalMensagem,friendly(e),"error")}}
function wireDilation(){const cancel=$("dilacaoCancelar");if(cancel){cancel.onclick=cancelarDilacao;return}const data=$("dilacaoData"),just=$("dilacaoJustificativa"),count=$("dilacaoContador"),review=$("dilacaoRevisao");if(!data||!just)return;just.oninput=()=>count.textContent=`${just.value.length}/1.500`;$("dilacaoRevisar").onclick=()=>{const atual=S.detalhe?.ciclo_selecionado?.prazo_em||S.atual?.prazo_em,nova=data.value?new Date(data.value+"T12:00:00"):null,prazo=new Date(String(atual).slice(0,10)+"T12:00:00"),text=just.value.trim();if(!nova)return msg(E.modalMensagem,"Informe a nova data pretendida.","warning");if(nova<=prazo)return msg(E.modalMensagem,"A nova data deve ser posterior ao prazo vigente.","warning");if(text.length<10)return msg(E.modalMensagem,"Informe uma justificativa com pelo menos 10 caracteres.","warning");const dias=Math.ceil((nova-prazo)/86400000);review.hidden=false;review.innerHTML=`<h4>Revisão da solicitação</h4><div class="dilation-compare"><div><span>Prazo vigente</span><strong>${fmtDate(prazo)}</strong></div><div><span>Prazo solicitado</span><strong>${fmtDate(nova)}</strong></div><div><span>Acréscimo</span><strong>${dias} ${dias===1?"dia":"dias"}</strong></div></div><div class="review-reason"><span>Justificativa</span><p>${esc(text)}</p></div><div class="integration-note"><strong>Confirmação</strong><span>O prazo permanecerá inalterado até a decisão do Gestor.</span></div><div class="dilation-actions"><button class="btn" id="dilacaoEditar" type="button">Editar</button><button class="btn btn-primary" id="dilacaoEnviar" type="button">Enviar solicitação</button></div>`;$("dilacaoForm").hidden=true;$("dilacaoEditar").onclick=()=>{review.hidden=true;$("dilacaoForm").hidden=false};$("dilacaoEnviar").onclick=()=>enviarDilacao(data.value,text);msg(E.modalMensagem,"")}}
function renderTreatment(){const p=S.detalhe.permissoes||{},c=S.detalhe.ciclo_selecionado||{},started=tratamentoIniciado(c);if(p.somente_leitura){E.painelTratamento.innerHTML=`<div class="treatment-readonly"><header><div><span class="card-kicker">Modo de consulta</span><h3>Ciclo de Tratamento Interno encerrado</h3></div><span class="badge status-closed">Somente leitura</span></header><div class="readonly-summary"><div><span>Resultado</span><strong>${esc(c.resultado_encerramento||"Não informado")}</strong></div><div><span>Encerramento</span><strong>${fmtDT(c.encerrado_em)}</strong></div><div><span>Movimentações</span><strong>${S.historico.length}</strong></div></div><p>Este ciclo não permite novas movimentações nem solicitação de dilação.</p></div>`;return}let actions="";if(!started&&p.pode_iniciar)actions+=`<article class="action-card action-start full"><div><span class="card-kicker">Etapa inicial</span><h3>Iniciar tratamento</h3><p>Registre o início para liberar observações, providências, conclusão e solicitação de dilação.</p></div><button class="btn btn-primary" data-action="start">Iniciar tratamento</button></article>`;if(started&&p.pode_registrar_observacao)actions+=`<article class="action-card action-observation"><span class="card-kicker">Análise</span><h3>Registrar observação</h3><p>Registre constatações e informações relevantes para o tratamento.</p><textarea class="control textarea" id="obsInput" maxlength="3000" placeholder="Digite a observação..."></textarea><div class="card-actions"><button class="btn btn-primary" data-action="OBSERVACAO">Registrar observação</button></div></article>`;if(started&&p.pode_registrar_providencia)actions+=`<article class="action-card action-providence"><span class="card-kicker">Ação adotada</span><h3>Registrar providência</h3><p>Descreva a providência executada durante o tratamento.</p><textarea class="control textarea" id="provInput" maxlength="3000" placeholder="Digite a providência..."></textarea><div class="card-actions"><button class="btn btn-primary" data-action="PROVIDENCIA">Registrar providência</button></div></article>`;if(started&&p.pode_encerrar)actions+=`<article class="action-card action-conclusion full"><span class="card-kicker">Conclusão</span><h3>Concluir tratamento</h3><p>Informe o resultado final. Após a confirmação, o ciclo ficará somente para consulta.</p><textarea class="control textarea" id="concInput" maxlength="3000" placeholder="Descreva o resultado do tratamento..."></textarea><div class="card-actions"><button class="btn btn-danger" data-action="CONCLUSAO">Concluir tratamento</button></div></article>`;E.painelTratamento.innerHTML=`<div class="treatment-shell ${started?"is-started":"is-pending"}"><section><div class="treatment-heading"><div><span class="card-kicker">Ações operacionais</span><h3>Tratamento do indício</h3></div><p>${started?"Todos os registros serão incluídos no Histórico integral.":"As demais ações serão exibidas após o início do tratamento."}</p></div><div class="treatment-grid polished">${actions||'<div class="table-state">Nenhuma ação disponível para o estado atual do ciclo.</div>'}</div></section>${dilacaoCard(p,c)}</div>`;restoreDraft("obsInput","observacao");restoreDraft("provInput","providencia");restoreDraft("concInput","conclusao");wireDilation()}
function renderProcesses(){const p=S.detalhe.permissoes||{},all=S.detalhe.processos_sei||[],active=all.filter(x=>x.processo_ativo),inactive=all.filter(x=>!x.processo_ativo);const form=p.pode_vincular_processo_sei?`<div class="table-toolbar"><strong>Processos SEI</strong><button class="btn btn-primary" data-process="new">+ Vincular processo</button></div><form class="embedded" id="processForm" hidden><div class="form-grid-v3"><div class="field"><label>Número *</label><input class="control" id="processNumber" required placeholder="00000.000000/0000-00"></div><div class="field"><label>Assunto</label><input class="control" id="processSubject"></div><div class="field wide"><label>Observação</label><textarea class="control textarea" id="processNote"></textarea></div><label class="check-option wide"><input type="checkbox" id="processMain"> Definir como principal</label></div><div class="form-actions"><button class="btn" type="button" data-process="cancel">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`:"";const list=(arr,inact=false)=>arr.length?arr.map(x=>`<article class="process-card ${inact?"inactive":""}"><div><h3>${esc(x.numero_processo)} ${x.processo_principal?'<span class="badge badge-primary">Principal</span>':''}</h3><p>${esc(x.assunto||"Sem assunto")}</p><small>Incluído por ${esc(x.incluido_por||"")} em ${fmtDT(x.incluido_em)}${inact?`<br>Inativado por ${esc(x.inativado_por||"")} em ${fmtDT(x.inativado_em)}<br>Motivo: ${esc(x.motivo_inativacao||"")}`:""}</small></div>${!inact?`<div class="process-actions">${p.pode_definir_processo_principal&&!x.processo_principal?`<button class="btn" data-main="${x.id_processo_sei}">Definir principal</button>`:""}${p.pode_inativar_processo_sei?`<button class="btn btn-danger" data-inactivate="${x.id_processo_sei}">Inativar</button>`:""}</div>`:""}</article>`).join(""):'<div class="table-state">Nenhum registro.</div>';E.painelProcessos.innerHTML=form+`<div class="process-groups"><section><h3 class="process-group-title">Ativos</h3><div class="process-list">${list(active)}</div></section><section><h3 class="process-group-title">Inativados</h3><div class="process-list">${list(inactive,true)}</div></section></div>`}
const historyMap={INICIO_TRATAMENTO:["Início do tratamento","history-start","▶"],VINCULO_PROCESSO_SEI:["Processo SEI vinculado","history-sei","⌁"],ALTERACAO_PROCESSO_SEI_PRINCIPAL:["Processo principal alterado","history-sei","⌁"],INATIVACAO_PROCESSO_SEI:["Processo SEI inativado","history-sei","⌁"],OBSERVACAO:["Observação registrada","history-observation","✎"],PROVIDENCIA:["Providência adotada","history-providence","✓"],SOLICITACAO_DILACAO_PRAZO:["Solicitação de dilação enviada","history-dilation","↗"],SOLICITACAO_DILACAO:["Solicitação de dilação enviada","history-dilation","↗"],CANCELAMENTO_SOLICITACAO_DILACAO:["Solicitação de dilação cancelada","history-dilation","×"],CANCELAMENTO_DILACAO:["Solicitação de dilação cancelada","history-dilation","×"],APROVACAO_DILACAO_PRAZO:["Dilação aprovada","history-dilation","✓"],APROVACAO_DILACAO_COM_AJUSTE:["Dilação aprovada com ajuste","history-dilation","✓"],APROVACAO_DILACAO:["Dilação aprovada","history-dilation","✓"],REJEICAO_DILACAO_PRAZO:["Dilação rejeitada","history-closed","×"],REJEICAO_DILACAO:["Dilação rejeitada","history-closed","×"],ALTERACAO_PRAZO:["Prazo do ciclo alterado","history-dilation","◷"],ENCERRAMENTO_INTERNO:["Tratamento encerrado","history-closed","■"]};
async function loadHistory(){const d=await rpc("listar_minhas_movimentacoes_demanda",{p_id_ciclo_tratamento:S.atual.id_ciclo_tratamento,p_codigo_movimentacao:null,p_data_inicial:null,p_data_final:null,p_pagina:1,p_tamanho_pagina:100});S.historico=d.itens||[];renderHistory()}
function historyCategory(code=""){return code.includes("PROCESSO")?"PROCESSO":code.includes("DILACAO")||code.includes("PRAZO")?"DILACAO":code.includes("ENCERR")?"ENCERRAMENTO":["OBSERVACAO","PROVIDENCIA","INICIO_TRATAMENTO"].includes(code)?"OPERACIONAL":"SISTEMA"}
function historyActor(x={}){return x.nome_executor||x.realizado_por||x.nome_usuario||x.usuario_nome||x.criado_por||x.executor?.nome_exibicao||"Sistema"}
function historyCategoryLabel(v){return({OPERACIONAL:"Operacional",PROCESSO:"Processo SEI",DILACAO:"Dilação e prazo",ENCERRAMENTO:"Encerramento",SISTEMA:"Sistema e administração"})[v]||v}
function historyOriginLabel(v){return({PAGINA_OPERADOR:"Página do Operador",AUTOMATICO:"Automático",SISTEMA:"Sistema",OPERACIONAL:"Operacional"})[v]||String(v||"Sistema").replaceAll("_"," ").toLowerCase().replace(/(^|\s)\S/g,m=>m.toUpperCase())}
function renderHistory(){E.painelHistorico.innerHTML=`<div class="history-filter-panel"><div class="history-filter-grid"><label class="field history-search"><span>Buscar no histórico</span><input class="control" id="historySearch" placeholder="Descrição, executor ou movimentação"></label><label class="field"><span>Categoria</span><select class="control" id="historyFilter"><option value="">Todas</option><option value="OPERACIONAL">Operacionais</option><option value="PROCESSO">Processos SEI</option><option value="DILACAO">Dilação e prazo</option><option value="ENCERRAMENTO">Encerramento</option><option value="SISTEMA">Sistema e administração</option></select></label><label class="field"><span>Data inicial</span><input class="control" type="date" id="historyStart"></label><label class="field"><span>Data final</span><input class="control" type="date" id="historyEnd"></label><label class="field"><span>Ordenação</span><select class="control" id="historyOrder"><option value="DESC">Mais recentes primeiro</option><option value="ASC">Mais antigos primeiro</option></select></label></div><div class="history-filter-actions"><span id="historySummary"></span><div><button class="btn" id="historyPdf" type="button">Gerar relatório textual em PDF</button><button class="btn btn-ghost" id="historyClear" type="button">Limpar</button><button class="btn btn-primary" id="historyApply" type="button">Aplicar filtros</button></div></div></div><div id="historyList"></div>`;$("historyApply").onclick=renderHistoryList;$("historyPdf").onclick=exportHistoryPdf;$("historyClear").onclick=()=>{["historySearch","historyFilter","historyStart","historyEnd"].forEach(id=>$(id).value="");$("historyOrder").value="DESC";renderHistoryList()};renderHistoryList()}
function renderHistoryList(){const q=($("historySearch")?.value||"").trim().toLowerCase(),cat=$("historyFilter")?.value||"",ini=$("historyStart")?.value?new Date($("historyStart").value+"T00:00:00"):null,fim=$("historyEnd")?.value?new Date($("historyEnd").value+"T23:59:59"):null,order=$("historyOrder")?.value||"DESC";let rows=S.historico.filter(x=>{const dt=new Date(x.realizada_em),m=historyMap[x.codigo_movimentacao]||[x.nome_movimentacao||"Movimentação"];const text=[m[0],x.descricao,historyActor(x)].join(" ").toLowerCase();return(!q||text.includes(q))&&(!cat||historyCategory(x.codigo_movimentacao)===cat)&&(!ini||dt>=ini)&&(!fim||dt<=fim)}).sort((a,b)=>(new Date(a.realizada_em)-new Date(b.realizada_em))*(order==="ASC"?1:-1));if($("historySummary"))$("historySummary").textContent=plural(rows.length,"movimentação encontrada","movimentações encontradas");$("historyList").innerHTML=rows.length?`<div class="timeline manager-style">${rows.map(x=>{const m=historyMap[x.codigo_movimentacao]||[x.nome_movimentacao||"Movimentação","history-default","•"],actor=historyActor(x),origin=x.origem||x.dados_complementares?.origem||historyCategory(x.codigo_movimentacao);return`<article class="timeline-item ${m[1]}"><span class="history-icon">${m[2]}</span><div class="history-content"><div class="history-heading"><div><strong>${esc(m[0])}</strong><span class="history-category">${esc(historyCategoryLabel(historyCategory(x.codigo_movimentacao)))}</span></div><time>${fmtDT(x.realizada_em)}</time></div>${x.descricao?`<p>${esc(x.descricao)}</p>`:""}<footer><span>Registrado por <strong>${esc(actor)}</strong></span><span>Origem: ${esc(historyOriginLabel(origin))}</span></footer></div></article>`}).join("")}</div>`:'<div class="history-empty"><strong>Nenhuma movimentação encontrada</strong><span>Ajuste os filtros ou consulte outro período.</span></div>'}
function confirm(title,body,label="Confirmar"){return new Promise(resolve=>{S.confirmar=resolve;E.confirmTitulo.textContent=title;E.confirmCorpo.innerHTML=body;E.confirmOk.textContent=label;E.confirmOverlay.hidden=false;E.confirmOk.focus()})}
function closeConfirm(v=false){E.confirmOverlay.hidden=true;S.confirmar?.(v);S.confirmar=null}
async function refreshModal(){const id=S.atual?.id_ciclo_tratamento;await loadList();if(id){const next=S.itens.find(x=>String(x.id_ciclo_tratamento)===String(id));if(next)await openModal(id);else closeModal()}}
async function action(name,args,success,draft){try{msg(E.modalMensagem,"Processando...");await rpc(name,args);if(draft)localStorage.removeItem(draftKey(draft));await refreshModal();msg(E.mensagem,success,"success")}catch(e){msg(E.modalMensagem,friendly(e),"error")}}
function switchTab(name){document.querySelectorAll("[data-panel]").forEach(x=>x.hidden=x.dataset.panel!==name);document.querySelectorAll("[data-tab]").forEach(x=>{const a=x.dataset.tab===name;x.classList.toggle("active",a);x.setAttribute("aria-selected",a)})}
function closeModal(){E.modalOverlay.hidden=true;document.body.style.overflow="";S.atual=S.detalhe=null;S.cpfVisivel=false;S.cpfCompleto=null;S.cpfCarregando=false;S.ultimoFoco?.focus()}
const CSV_COLUMNS={identificador:{label:"Número do indício",group:"Identificação",value:x=>x.identificador_do_indicio},nome:{label:"Nome",group:"Identificação",value:x=>x.nome_atual},cpf:{label:"CPF",group:"Identificação",value:x=>maskCpf(x.cpf_mascarado)},tipo:{label:"Tipo de indício",group:"Identificação",value:x=>x.tipo_indicio},base:{label:"Base de dados",group:"Origem",value:x=>x.base_de_dados},vinculos:{label:"Situação funcional",group:"Origem",value:x=>x.situacoes_funcionais_resumo||"Não informado"},situacao:{label:"Situação",group:"Tratamento",value:x=>labelStatus(x.codigo_status_ciclo,x.nome_status_ciclo)},prioridade:{label:"Prioridade",group:"Tratamento",value:x=>x.nome_prioridade||"Não definida"},prazo:{label:"Prazo",group:"Tratamento",value:x=>fmtDate(x.prazo_em)},situacaoPrazo:{label:"Situação do prazo",group:"Tratamento",value:x=>labelPrazo(x.situacao_prazo)},encerramento:{label:"Data do encerramento",group:"Tratamento",value:x=>fmtDT(closedAt(x))},papel:{label:"Meu papel",group:"Tratamento",value:x=>x.nome_papel},ciclo:{label:"Ciclo de Tratamento Interno",group:"Tratamento",value:x=>x.numero_ciclo||x.numero_ciclo_atual},modo:{label:"Modo de trabalho",group:"Tratamento",value:x=>x.nome_modo||x.codigo_modo},inicio:{label:"Data de início",group:"Tratamento",value:x=>fmtDT(x.iniciado_em)},processo:{label:"Processo SEI principal",group:"Processos SEI",value:x=>x.processo_sei_principal||"Nenhum"},qtdProcessos:{label:"Quantidade de processos SEI",group:"Processos SEI",value:x=>Number(x.quantidade_processos_sei_ativos||0)}};
const CSV_PRESETS={RESUMIDO:["identificador","nome","cpf","tipo","situacao","prioridade","prazo","situacaoPrazo","papel"],DETALHADO:["identificador","nome","cpf","tipo","base","vinculos","situacao","prioridade","prazo","situacaoPrazo","papel","ciclo","modo","inicio","processo","qtdProcessos"]};
function csvSafe(v){let s=String(v??"");if(/^[=+\-@\t\r]/.test(s))s="'"+s;return `"${s.replaceAll('"','""')}"`}
function csvSelected(name){return document.querySelector(`input[name="${name}"]:checked`)?.value}
function csvAvailableKeys(){const concluded=S.escopo==="CONCLUIDAS";return Object.keys(CSV_COLUMNS).filter(k=>concluded?k!=="prazo"&&k!=="situacaoPrazo":k!=="encerramento")}
function csvPreset(profile){return (CSV_PRESETS[profile]||CSV_PRESETS.DETALHADO).filter(k=>csvAvailableKeys().includes(k))}
function renderCsvColumns(){const keys=csvAvailableKeys(),groups={};keys.forEach(k=>(groups[CSV_COLUMNS[k].group]??=[]).push(k));E.csvColumnsGrid.innerHTML=Object.entries(groups).map(([group,items])=>`<fieldset><legend>${esc(group)}</legend>${items.map(k=>`<label class="csv-column-option"><input type="checkbox" value="${k}" ${S.csvColunas.includes(k)?"checked":""}><span>${esc(CSV_COLUMNS[k].label)}</span></label>`).join("")}</fieldset>`).join("");E.csvColumnsGrid.querySelectorAll('input[type="checkbox"]').forEach(x=>x.onchange=()=>{S.csvColunas=[...E.csvColumnsGrid.querySelectorAll('input:checked')].map(i=>i.value);updateCsvColumnsCount();const custom=document.querySelector('input[name="csvPerfil"][value="PERSONALIZADO"]');custom.checked=true;E.csvColumnsSection.hidden=false;updateCsvSummary()});updateCsvColumnsCount()}
function updateCsvColumnsCount(){if(E.csvColumnsCount)E.csvColumnsCount.textContent=plural(S.csvColunas.length,"coluna selecionada","colunas selecionadas")}
function applyCsvProfile(profile){if(profile!=="PERSONALIZADO")S.csvColunas=csvPreset(profile);else if(!S.csvColunas.length)S.csvColunas=csvPreset("DETALHADO");E.csvColumnsSection.hidden=profile!=="PERSONALIZADO";renderCsvColumns();updateCsvSummary()}
function updateCsvSummary(){if(!E.csvResumo)return;const scope=csvSelected("csvEscopo")||"PAGINA",profile=csvSelected("csvPerfil")||"RESUMIDO";E.csvResumo.innerHTML=`<div><span>Grupo</span><strong>${S.escopo==="ATIVAS"?"Indícios atuais":S.escopo==="CONCLUIDAS"?"Indícios concluídos":"Participações anteriores"}</strong></div><div><span>Escopo</span><strong>${scope==="PAGINA"?plural(S.itens.length,"registro da página","registros da página"):"Todos os registros filtrados"}</strong></div><div><span>Perfil</span><strong>${profile==="RESUMIDO"?"Resumido":profile==="DETALHADO"?"Operacional":"Personalizado"}</strong></div><div><span>Colunas</span><strong>${S.csvColunas.length} selecionadas</strong></div>`}
function openCsv(){S.csvColunas=csvPreset("RESUMIDO");document.querySelector('input[name="csvPerfil"][value="RESUMIDO"]').checked=true;E.csvColumnsSection.hidden=true;renderCsvColumns();E.csvOverlay.hidden=false;document.body.style.overflow="hidden";msg(E.csvMensagem,"");updateCsvSummary();E.csvOverlay.querySelector(".export-modal").focus()}
function closeCsv(){if(S.csvExportando)return;E.csvOverlay.hidden=true;document.body.style.overflow=E.modalOverlay.hidden?"":"hidden"}
async function allFilteredItems(){const batch=200,first=await rpc("listar_minhas_demandas",{...params(),p_pagina:1,p_tamanho_pagina:batch}),items=[...(first.itens||[])],pages=Number(first.paginacao?.total_paginas||1);for(let page=2;page<=pages;page++){const d=await rpc("listar_minhas_demandas",{...params(),p_pagina:page,p_tamanho_pagina:batch});items.push(...(d.itens||[]))}return items}
function csvDataset(items){const keys=S.csvColunas.filter(k=>CSV_COLUMNS[k]);const rows=items.map(x=>keys.map(k=>CSV_COLUMNS[k].value(x)));return[[...keys.map(k=>CSV_COLUMNS[k].label)],...rows].map(r=>r.map(csvSafe).join(";")).join("\r\n")}
async function exportCsv(){if(S.csvExportando)return;if(!S.csvColunas.length)return msg(E.csvMensagem,"Selecione pelo menos uma coluna.","warning");try{S.csvExportando=true;E.csvGerar.disabled=true;E.csvGerar.textContent="Preparando...";msg(E.csvMensagem,"Buscando os registros selecionados...","");const scope=csvSelected("csvEscopo")||"PAGINA",profile=csvSelected("csvPerfil")||"RESUMIDO",items=scope==="PAGINA"?S.itens:await allFilteredItems();if(!items.length)throw Error("Nenhum registro disponível para exportação.");const file=`indicios_${S.escopo.toLowerCase()}_${profile.toLowerCase()}_${new Date().toISOString().slice(0,10)}.csv`;download(file,"\ufeff"+csvDataset(items),"text/csv;charset=utf-8");msg(E.csvMensagem,`${plural(items.length,"registro exportado","registros exportados")} com sucesso.`,"success")}catch(e){msg(E.csvMensagem,friendly(e),"error")}finally{S.csvExportando=false;E.csvGerar.disabled=false;E.csvGerar.textContent="Gerar CSV"}}
function download(name,data,type){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportHistoryPdf(){
  if(!S.detalhe){msg(E.modalMensagem,"Os detalhes do indício ainda não foram carregados.","warning");return}
  if(!window.jspdf?.jsPDF){msg(E.modalMensagem,"A biblioteca de geração do PDF não foi carregada. Atualize a página e tente novamente.","error");return}
  const button=$("historyPdf"),oldText=button?.textContent;
  if(button){button.disabled=true;button.textContent="Gerando PDF..."}
  try{
    const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:"portrait",unit:"mm",format:"a4",compress:true,putOnlyUsedFonts:true});
    const d=S.detalhe,c=d.ciclo_selecionado||{},participacao=d.minha_participacao||{},processos=d.processos_sei||[],equipe=c.equipe||d.equipe||[],movs=[...S.historico].sort((a,b)=>new Date(a.realizada_em)-new Date(b.realizada_em));
    const pageW=doc.internal.pageSize.getWidth(),pageH=doc.internal.pageSize.getHeight(),margin=16,contentW=pageW-margin*2,bottom=18;
    let y=20;
    const clean=v=>v===null||v===undefined||v===""?"Não informado":String(v),maskedCpf=cpfMask();
    const ensure=h=>{if(y+h>pageH-bottom){doc.addPage();y=20;drawContinuationHeader()}};
    const textLines=(text,width=contentW,size=9)=>{doc.setFontSize(size);return doc.splitTextToSize(clean(text),width)};
    const drawContinuationHeader=()=>{doc.setTextColor(21,94,239);doc.setFont("helvetica","bold");doc.setFontSize(9);doc.text("Sistema de Monitoramento de Indícios",margin,10);doc.setDrawColor(180,195,215);doc.line(margin,13,pageW-margin,13);doc.setTextColor(23,32,51)};
    const section=title=>{ensure(13);y+=2;doc.setFillColor(239,244,255);doc.roundedRect(margin,y,contentW,8,1.5,1.5,"F");doc.setTextColor(24,73,169);doc.setFont("helvetica","bold");doc.setFontSize(11);doc.text(title,margin+3,y+5.5);doc.setTextColor(23,32,51);y+=12};
    const field=(label,value,x,w)=>{const valueLines=textLines(value,w-6,8.7),h=Math.max(14,8+valueLines.length*4);ensure(h+2);doc.setDrawColor(208,213,221);doc.setFillColor(248,250,252);doc.roundedRect(x,y,w,h,1.5,1.5,"FD");doc.setTextColor(102,112,133);doc.setFont("helvetica","normal");doc.setFontSize(6.8);doc.text(String(label).toUpperCase(),x+3,y+4);doc.setTextColor(23,32,51);doc.setFont("helvetica","bold");doc.setFontSize(8.7);doc.text(valueLines,x+3,y+8.5);return h};
    const row=(items)=>{const gap=3,w=(contentW-gap*(items.length-1))/items.length;let heights=items.map(([l,v])=>{doc.setFontSize(8.7);return Math.max(14,8+doc.splitTextToSize(clean(v),w-6).length*4)}),h=Math.max(...heights);ensure(h+2);items.forEach(([l,v],i)=>{const x=margin+i*(w+gap);doc.setDrawColor(208,213,221);doc.setFillColor(248,250,252);doc.roundedRect(x,y,w,h,1.5,1.5,"FD");doc.setTextColor(102,112,133);doc.setFont("helvetica","normal");doc.setFontSize(6.8);doc.text(String(l).toUpperCase(),x+3,y+4);doc.setTextColor(23,32,51);doc.setFont("helvetica","bold");doc.setFontSize(8.7);doc.text(doc.splitTextToSize(clean(v),w-6),x+3,y+8.5)});y+=h+3};
    const paragraph=(label,value)=>{const lines=textLines(value,contentW-6,8.8),h=10+lines.length*4;ensure(h+2);doc.setDrawColor(208,213,221);doc.setFillColor(255,255,255);doc.roundedRect(margin,y,contentW,h,1.5,1.5,"FD");doc.setTextColor(102,112,133);doc.setFont("helvetica","normal");doc.setFontSize(6.8);doc.text(String(label).toUpperCase(),margin+3,y+4);doc.setTextColor(23,32,51);doc.setFontSize(8.8);doc.text(lines,margin+3,y+8.5);y+=h+3};
    const subsection=title=>{ensure(9);doc.setTextColor(71,84,103);doc.setFont("helvetica","bold");doc.setFontSize(9.5);doc.text(title,margin,y+4);doc.setTextColor(23,32,51);y+=8};
    const duration=(()=>{if(!c.iniciado_em)return"Não calculado";const end=c.encerrado_em?new Date(c.encerrado_em):new Date(),minutes=Math.max(0,Math.floor((end-new Date(c.iniciado_em))/60000)),days=Math.floor(minutes/1440),hours=Math.floor((minutes%1440)/60),mins=minutes%60;return [days&&`${days} ${days===1?"dia":"dias"}`,hours&&`${hours} ${hours===1?"hora":"horas"}`,mins&&`${mins} ${mins===1?"minuto":"minutos"}`].filter(Boolean).join(", ")||"Menos de 1 minuto"})();

    doc.setTextColor(21,94,239);doc.setFont("helvetica","bold");doc.setFontSize(19);doc.text("Relatório detalhado do tratamento do indício",margin,y);y+=7;
    doc.setTextColor(71,84,103);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text("Documento operacional textual, pesquisável e copiável",margin,y);y+=5;
    doc.setDrawColor(21,94,239);doc.setLineWidth(.8);doc.line(margin,y,pageW-margin,y);y+=8;doc.setTextColor(23,32,51);

    section("1. Identificação do indício");
    row([["Número do indício",d.identificador_do_indicio],["Base de dados",d.base_de_dados],["Situação",labelStatus(c.codigo_status_ciclo,c.nome_status_ciclo)]]);
    paragraph("Tipo de indício",d.tipo_indicio);paragraph("Descrição",d.descricao_indicio);

    section("2. Identificação da pessoa");
    row([["Nome",d.nome_atual],["CPF",maskedCpf]]);paragraph("Situação funcional",d.situacoes_funcionais_resumo||d.situacao_funcional);

    section("3. Ciclo de Tratamento Interno");
    row([["Número do ciclo",c.numero_ciclo],["Situação",labelStatus(c.codigo_status_ciclo,c.nome_status_ciclo)],["Versão",c.versao_ciclo||c.versao]]);
    row([["Prioridade",c.nome_prioridade||S.atual?.nome_prioridade],["Prazo",c.prazo_em?fmtDate(c.prazo_em):fmtDate(S.atual?.prazo_em)],["Papel do operador",participacao.nome_papel||participacao.codigo_papel||S.atual?.nome_papel]]);
    row([["Abertura",fmtDT(c.aberto_em)],["Início",fmtDT(c.iniciado_em)],["Encerramento",fmtDT(c.encerrado_em)]]);
    row([["Duração",duration],["Retorno",c.indicador_retorno?"Sim":"Não"],["Participação ativa",participacao.participacao_ativa===true?"Sim":participacao.participacao_ativa===false?"Não":"Não informado"]]);
    if(c.motivo_retorno)paragraph("Motivo do retorno",c.motivo_retorno);
    paragraph("Resultado do tratamento",c.resultado_encerramento||"Tratamento ainda não encerrado.");

    section("4. Equipe do ciclo");
    if(equipe.length){equipe.forEach((x,i)=>{subsection(`${i+1}. ${clean(x.nome_exibicao||x.nome)}`);row([["Papel",x.nome_papel||x.codigo_papel],["Participação ativa",x.participacao_ativa?"Sim":"Não"],["Atribuição",fmtDT(x.atribuido_em)]]);if(x.encerrado_em)row([["Participação encerrada em",fmtDT(x.encerrado_em)]]);})}else paragraph("Equipe","Equipe não informada no contrato atual.");

    section("5. Processos SEI");
    if(processos.length){processos.forEach((x,i)=>{subsection(`${i+1}. ${clean(x.numero_processo)}${x.processo_principal?" (principal)":""}`);row([["Situação",x.processo_ativo?"Ativo":"Inativado"],["Incluído por",x.incluido_por],["Incluído em",fmtDT(x.incluido_em)]]);paragraph("Assunto",x.assunto||"Não informado");if(x.observacao)paragraph("Observação",x.observacao);if(!x.processo_ativo){row([["Inativado por",x.inativado_por],["Inativado em",fmtDT(x.inativado_em)]]);paragraph("Motivo da inativação",x.motivo_inativacao)}})}else paragraph("Processos SEI","Nenhum processo SEI vinculado a este ciclo.");

    section("6. Resumo das movimentações");
    const counts=movs.reduce((a,x)=>(a[x.codigo_movimentacao]=(a[x.codigo_movimentacao]||0)+1,a),{});
    row([["Total",movs.length],["Observações",counts.OBSERVACAO||0],["Providências",counts.PROVIDENCIA||0],["Processos vinculados",counts.VINCULO_PROCESSO_SEI||0]]);
    row([["Solicitações de dilação",counts.SOLICITACAO_DILACAO_PRAZO||0],["Cancelamentos de dilação",counts.CANCELAMENTO_SOLICITACAO_DILACAO||0],["Conclusões",counts.ENCERRAMENTO_INTERNO||0]]);

    section("7. Histórico integral");
    if(movs.length){movs.forEach((x,i)=>{const map=historyMap[x.codigo_movimentacao]||[x.nome_movimentacao||"Movimentação"],actor=historyActor(x),category=historyCategoryLabel(historyCategory(x.codigo_movimentacao));const descLines=textLines(x.descricao||"Movimentação registrada sem descrição adicional.",contentW-8,8.5);const h=19+descLines.length*4;ensure(h+3);doc.setDrawColor(185,200,222);doc.setFillColor(248,250,252);doc.roundedRect(margin,y,contentW,h,1.5,1.5,"FD");doc.setTextColor(21,94,239);doc.setFont("helvetica","bold");doc.setFontSize(9.2);doc.text(`${String(i+1).padStart(2,"0")}. ${map[0]}`,margin+4,y+5);doc.setTextColor(102,112,133);doc.setFont("helvetica","normal");doc.setFontSize(7.2);doc.text(fmtDT(x.realizada_em),pageW-margin-4,y+5,{align:"right"});doc.setTextColor(23,32,51);doc.setFontSize(8.5);doc.text(descLines,margin+4,y+10);doc.setTextColor(71,84,103);doc.setFontSize(7.2);doc.text(`Categoria: ${category} | Registrado por: ${actor} | Origem: ${historyOriginLabel(x.origem||x.dados_complementares?.origem||"SISTEMA")}`,margin+4,y+h-3);y+=h+3})}else paragraph("Histórico","Nenhuma movimentação foi localizada.");

    section("8. Informações da emissão");
    row([["Emitido por",S.ctx?.nome_exibicao],["Perfil",S.ctx?.nome_perfil],["Data e hora",fmtDT(new Date())]]);
    paragraph("Escopo","Relatório do Ciclo de Tratamento Interno selecionado, com CPF mascarado e histórico disponível ao Operador.");

    const total=doc.getNumberOfPages();for(let page=1;page<=total;page++){doc.setPage(page);doc.setDrawColor(180,195,215);doc.line(margin,pageH-12,pageW-margin,pageH-12);doc.setTextColor(102,112,133);doc.setFont("helvetica","normal");doc.setFontSize(7.2);doc.text("Sistema de Monitoramento de Indícios",margin,pageH-7);doc.text(`Página ${page} de ${total}`,pageW-margin,pageH-7,{align:"right"})}
    const filename=`relatorio_indicio_${d.identificador_do_indicio}_ciclo_${c.numero_ciclo||1}_${new Date().toISOString().slice(0,10)}.pdf`;
    doc.save(filename);msg(E.modalMensagem,"Relatório textual gerado com sucesso.","success");
  }catch(e){console.error(e);msg(E.modalMensagem,"Não foi possível gerar o relatório em PDF.","error")}
  finally{if(button){button.disabled=false;button.textContent=oldText||"Gerar relatório em PDF"}}
}
function setup(){document.querySelectorAll("[data-main-tab]").forEach(b=>b.onclick=async()=>{document.querySelectorAll("[data-main-tab]").forEach(x=>{const a=x===b;x.classList.toggle("active",a);x.setAttribute("aria-selected",a)});const tab=b.dataset.mainTab;E.secaoPainel.hidden=tab!=="painel";E.secaoDemandas.hidden=tab==="painel";if(tab==="painel")await loadPanel();else{S.escopo=tab;S.pagina=1;E.tituloTabela.textContent=tab==="ATIVAS"?"Indícios atuais":tab==="CONCLUIDAS"?"Indícios concluídos":"Participações anteriores";await loadList()}});E.aplicar.onclick=()=>{S.pagina=1;loadList()};E.limpar.onclick=()=>{[E.busca,E.status,E.prioridade,E.papel,E.prazo,E.processo].forEach(x=>x.value="");S.pagina=1;loadList()};E.toggleFiltros.onclick=()=>{E.avancados.hidden=!E.avancados.hidden;E.toggleFiltros.setAttribute("aria-expanded",!E.avancados.hidden)};E.porPagina.onchange=()=>{S.tamanho=+E.porPagina.value;S.pagina=1;loadList()};E.anterior.onclick=()=>{S.pagina--;loadList()};E.proxima.onclick=()=>{S.pagina++;loadList()};E.exportarCsv.onclick=openCsv;E.csvFechar.onclick=E.csvCancelar.onclick=closeCsv;E.csvGerar.onclick=exportCsv;E.csvOverlay.onclick=e=>{if(e.target===E.csvOverlay)closeCsv()};document.querySelectorAll('input[name="csvEscopo"]').forEach(x=>x.onchange=()=>{renderCsvColumns();updateCsvSummary()});document.querySelectorAll('input[name="csvPerfil"]').forEach(x=>x.onchange=()=>applyCsvProfile(x.value));E.csvSelecionarTodas.onclick=()=>{S.csvColunas=csvAvailableKeys();renderCsvColumns();document.querySelector('input[name="csvPerfil"][value="PERSONALIZADO"]').checked=true;E.csvColumnsSection.hidden=false;updateCsvSummary()};E.csvLimparColunas.onclick=()=>{S.csvColunas=[];renderCsvColumns();document.querySelector('input[name="csvPerfil"][value="PERSONALIZADO"]').checked=true;E.csvColumnsSection.hidden=false;updateCsvSummary()};E.csvRestaurarColunas.onclick=()=>applyCsvProfile("DETALHADO");E.tbody.onclick=e=>{const b=e.target.closest("[data-view]");if(b)openModal(b.dataset.view)};document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));E.fecharModal.onclick=E.fecharRodape.onclick=closeModal;E.modalOverlay.onclick=e=>{if(e.target===E.modalOverlay)closeModal()};E.confirmCancelar.onclick=()=>closeConfirm(false);E.confirmOk.onclick=()=>closeConfirm(true);E.atualizarBtn.onclick=()=>E.secaoPainel.hidden?loadList():loadPanel();E.aplicarPainel.onclick=loadPanel;E.temaBtn.onclick=()=>{const t=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=t;localStorage.setItem("tema",t)};E.sairBtn.onclick=async()=>{await supabase.auth.signOut();location.replace("../index.html")};document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(!E.csvOverlay.hidden)closeCsv();else if(!E.confirmOverlay.hidden)closeConfirm(false);else if(!E.modalOverlay.hidden)closeModal()}});E.painelTratamento.onclick=async e=>{const b=e.target.closest("[data-action]");if(!b)return;const c=S.detalhe.ciclo_selecionado,type=b.dataset.action;if(type==="start")return action("iniciar_tratamento_individual",{p_id_ciclo_tratamento:c.id_ciclo_tratamento,p_versao_esperada:c.versao_ciclo,p_id_data_inicio:todayId()},"Tratamento iniciado.");const id=type==="OBSERVACAO"?"obsInput":type==="PROVIDENCIA"?"provInput":"concInput",text=$(id)?.value.trim();if(!text)return msg(E.modalMensagem,"Preencha o campo antes de continuar.","warning");if(type==="CONCLUSAO"&&!(await confirm("Confirmar encerramento",`<p>O tratamento será encerrado internamente.</p><p><b>Resultado:</b> ${esc(text)}</p>`,"Encerrar ciclo")))return;const name=type==="OBSERVACAO"?"registrar_observacao_individual":type==="PROVIDENCIA"?"registrar_providencia_individual":"encerrar_tratamento_individual",args=type==="CONCLUSAO"?{p_id_ciclo_tratamento:c.id_ciclo_tratamento,p_versao_esperada:c.versao_ciclo,p_id_data_encerramento:todayId(),p_resultado_encerramento:text}:{p_id_ciclo_tratamento:c.id_ciclo_tratamento,p_versao_esperada:c.versao_ciclo,p_id_data_movimentacao:todayId(),p_descricao:text,p_dados_complementares:{origem:"PAGINA_OPERADOR"}};action(name,args,type==="CONCLUSAO"?"Tratamento encerrado. O indício foi movido para Concluídos.":"Registro salvo.",type==="OBSERVACAO"?"observacao":type==="PROVIDENCIA"?"providencia":"conclusao")};E.painelProcessos.onclick=async e=>{const n=e.target.closest("[data-process]"),m=e.target.closest("[data-main]"),i=e.target.closest("[data-inactivate]");if(n){const f=$("processForm");f.hidden=n.dataset.process!=="new"}if(m){const p=S.detalhe.processos_sei.find(x=>String(x.id_processo_sei)===m.dataset.main);if(await confirm("Alterar processo principal",`<p>Definir <b>${esc(p.numero_processo)}</b> como principal?</p>`))action("definir_processo_sei_principal",{p_id_processo_sei:p.id_processo_sei,p_versao_processo_esperada:p.versao,p_versao_ciclo_esperada:S.detalhe.ciclo_selecionado.versao_ciclo,p_id_data_movimentacao:todayId()},"Processo principal alterado.")}if(i){const p=S.detalhe.processos_sei.find(x=>String(x.id_processo_sei)===i.dataset.inactivate);const ok=await confirm("Inativar processo",`<p>Informe o motivo para inativar <b>${esc(p.numero_processo)}</b>.</p><label class="field"><span>Justificativa obrigatória</span><textarea class="control textarea" id="inactivateReason" maxlength="1000"></textarea></label>`,"Inativar processo");const reason=$("inactivateReason")?.value.trim();if(ok&&!reason)return msg(E.modalMensagem,"Informe a justificativa da inativação.","warning");if(ok&&reason)action("inativar_processo_sei_individual",{p_id_processo_sei:p.id_processo_sei,p_versao_processo_esperada:p.versao,p_versao_ciclo_esperada:S.detalhe.ciclo_selecionado.versao_ciclo,p_id_data_inativacao:todayId(),p_motivo_inativacao:reason},"Processo inativado.")}};E.painelProcessos.onsubmit=e=>{e.preventDefault();action("adicionar_processo_sei_individual",{p_id_ciclo_tratamento:S.detalhe.ciclo_selecionado.id_ciclo_tratamento,p_versao_esperada:S.detalhe.ciclo_selecionado.versao_ciclo,p_id_data_inclusao:todayId(),p_numero_processo:$("processNumber").value,p_assunto:$("processSubject").value||null,p_observacao:$("processNote").value||null,p_processo_principal:$("processMain").checked},"Processo vinculado.")}}
E.alternarCpfModalBtn?.addEventListener("click",toggleCpf);
(async()=>{try{document.documentElement.dataset.theme=localStorage.getItem("tema")||"light";const end=new Date(),start=new Date(Date.now()-29*86400000);E.painelFim.value=end.toISOString().slice(0,10);E.painelInicio.value=start.toISOString().slice(0,10);setup();await context();await loadPanel()}catch(e){if(e.message!=="SESSAO_AUSENTE")msg(E.mensagem,friendly(e),"error")}})();
